// Home Health Aide Practice Test 3. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–2.
import {q, mix} from './q.js';
const BAL='Balduzzi, Homemaker Home Health Aide', HART='Leahy, Fuzy & Grafe, Providing Home Care';
const RESP='Responsibilities and Legal/Ethical Issues', COMM='Effective Communication', INF='Infection Control and Safety', BODY='Body Systems and Common Disorders', SPEC='Caring for Special Populations', SKILL='Basic Healthcare Skills';

export default {
 id:'home-health-aide-3',
 event:'Home Health Aide',
 title:'Practice Test 3',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Balduzzi’s Homemaker Home Health Aide and Leahy, Fuzy & Grafe’s Providing Home Care',
 plan:[{area:RESP,weight:10},{area:COMM,weight:6},{area:INF,weight:10},{area:BODY,weight:40},{area:SPEC,weight:24},{area:SKILL,weight:10}],
 questions:mix([
  q(RESP,'A client offers the aide $50 as a thank-you gift. What should the aide do?','Politely refuse the gift',['Accept it and keep it quiet','Accept it and split it with staff','Ask for a larger gift next time'],'A','Accepting money or gifts can look like taking advantage of a client and is against agency policy.',HART),
  q(RESP,'Which task is within a home health aide’s scope of practice?','Helping a client bathe',['Changing a sterile dressing','Adjusting insulin doses','Giving IV medications'],'B','Aides help with personal care and activities of daily living, not tasks that need nursing judgment.',HART),
  q(RESP,'A client’s neighbor asks how the client is doing after surgery. What should the aide say?','“I can’t share that information.”',['“She is doing poorly after surgery.”','“Let me show you her care notes.”','“Call her daughter for the details.”'],'C','HIPAA protects the client’s health information from people who do not need it for care.',HART),
  q(RESP,'Which act by an aide could be considered false imprisonment?','Restraining a client without an order',['Helping a client walk to the kitchen','Reminding a client to drink water','Opening curtains when asked to'],'D','Keeping a client from moving freely without a legal order violates the client’s rights.',HART),
  q(RESP,'Why must an aide follow the care plan exactly?','It lists the care ordered for the client',['It is only a suggestion for the aide','The family can change it at any time','It applies only to the first visit'],'A','Changes to care must come from the supervising nurse, who updates the plan.',HART),
  q(COMM,'Which is an example of an open-ended question?','“How did you sleep last night?”',['“Did you sleep well last night?”','“Are you in pain right now?”','“Do you want juice or water?”'],'B','Open-ended questions invite the client to share more than a yes or no answer.',HART),
  q(COMM,'A client with aphasia after a stroke has trouble finding words. What helps most?','Use a picture board and give time',['Finish every sentence for the client','Speak loudly and quickly to them','Avoid talking to the client at all'],'C','Patience and communication aids reduce frustration and help the client express needs.',HART),
  q(COMM,'Which observation is an objective observation?','The client’s ankles are swollen',['The client says she feels dizzy','The client reports a headache','The client says she feels sad'],'D','Objective observations are things the aide can see, hear, smell or measure.',HART),
  q(INF,'Which link in the chain of infection does hand hygiene mainly break?','Mode of transmission',['Source of infection','Susceptible host','Causative agent only'],'A','Clean hands stop germs from traveling from one person or surface to another.',BAL),
  q(INF,'How long should an aide rub hands with soap during handwashing?','At least 20 seconds',['About 2 seconds','About 5 seconds','Exactly 1 second'],'B','Rubbing all surfaces for at least 20 seconds removes more germs.',BAL),
  q(INF,'What should an aide do with soiled linens in a client’s home?','Hold them away from the uniform',['Shake them out to remove dirt','Place them on the clean bed','Carry them pressed to the chest'],'C','Holding linens away keeps germs off the aide’s clothing and other surfaces.',BAL),
  q(INF,'What should the aide check before using an electrical appliance in a client’s home?','The cord for fraying or damage',['The brand name on the appliance','How old the appliance looks','The color of the power cord'],'D','Damaged cords can cause shocks and fires and should be reported.',BAL),
  q(INF,'Which practice reduces the risk of carbon monoxide poisoning at home?','Working CO detectors',['Running cars in a closed garage','Using a gas oven to heat rooms','Blocking furnace air vents'],'A','Carbon monoxide has no smell, so detectors are needed to warn people.',BAL),
  q(BODY,'Which disorder causes loss of insulin production and usually begins in childhood?','Type 1 diabetes',['Type 2 diabetes','Gestational diabetes','Diabetes insipidus'],'B','People with type 1 diabetes need insulin every day to survive.',HART),
  q(BODY,'Which symptom is common in a client with Parkinson disease?','A shuffling walk and tremor',['Sudden one-sided weakness','Yellowing of the skin','High fever and stiff neck'],'C','Parkinson disease affects movement, causing tremor and stiffness that get worse over time.',HART),
  q(BODY,'A client with a urinary catheter should have the drainage bag kept:','Below the level of the bladder',['Above the level of the bladder','On the bed beside the client','Lying on the floor at all times'],'D','Keeping the bag low prevents urine from flowing back and causing infection.',HART),
  q(BODY,'Which condition causes inflammation of the joints that is often worse in the morning?','Rheumatoid arthritis',['Osteoporosis','Muscular dystrophy','Gout of the spine'],'A','Rheumatoid arthritis is an autoimmune disease that affects joints on both sides of the body.',HART),
  q(BODY,'Which sign suggests a client with diabetes may have low blood sugar?','Sweating, shaking and confusion',['Fruity breath and deep breathing','Hot, dry skin and thirst','Frequent urination and hunger'],'B','Low blood sugar comes on quickly and needs fast-acting sugar if the client can swallow.',HART),
  q(BODY,'Which body system includes the kidneys and bladder?','Urinary system',['Endocrine system','Nervous system','Integumentary system'],'C','The urinary system filters waste from the blood and removes it as urine.',HART),
  q(BODY,'Which diet change helps a client with heart disease?','Less saturated fat and salt',['More fried foods and salt','More sugar and soda','Fewer fruits and vegetables'],'D','Heart-healthy diets limit saturated fat, salt and added sugar.',HART),
  q(BODY,'Which symptom suggests a client with asthma is having an attack?','Wheezing and trouble breathing',['Slow, deep and easy breathing','Warm, dry and pink skin','A steady, normal heart rate'],'A','The client should use the rescue inhaler as ordered, and the aide should report the attack.',HART),
  q(BODY,'Why is a client with COPD at risk for respiratory infections?','Damaged lungs clear mucus poorly',['COPD strengthens the lungs','COPD only affects the heart','COPD prevents all coughing'],'B','Flu and pneumonia vaccines help protect clients with chronic lung disease.',HART),
  q(BODY,'Which sign may indicate a client has a urinary tract infection?','Burning and frequent urination',['Clear, pale and odorless urine','Normal amounts of urine output','Easy, painless urination'],'C','Older adults may also show confusion as the main sign of infection.',HART),
  q(BODY,'Which condition is a progressive loss of memory and thinking ability?','Alzheimer’s disease',['Cerebral palsy','Spina bifida','Down syndrome'],'D','Alzheimer’s disease is the most common cause of dementia in older adults.',HART),
  q(BODY,'A client with heart failure should be weighed:','Daily at the same time',['Once each month','Only when swollen','Only at the doctor'],'A','Weigh at the same time each day, since sudden weight gain can be an early sign of fluid buildup.',HART),
  q(BODY,'Which skin change is normal with aging?','Thinner, drier skin',['New open sores','Sudden yellowing','Bright red rashes'],'B','Older skin tears and bruises more easily, so gentle handling is needed.',HART),
  q(BODY,'Which disorder causes a sudden, severe pain in the big toe from uric acid crystals?','Gout',['Bursitis','Scoliosis','Sciatica'],'C','Limiting alcohol and organ meats can help reduce gout attacks.',HART),
  q(BODY,'Which sign should be reported for a client recovering from a hip replacement?','Calf pain and swelling',['Mild tiredness after a walk','A good appetite at meals','Normal bowel movements'],'D','Calf pain, warmth and swelling may signal a blood clot in the leg after surgery.',HART),
  q(BODY,'Which symptom is typical of hyperthyroidism?','Weight loss and feeling hot',['Weight gain and feeling cold','Slow pulse and dry skin','Constipation and fatigue'],'A','An overactive thyroid speeds up metabolism, causing weight loss, heat intolerance and a fast pulse.',HART),
  q(BODY,'Which condition causes the airways to stay inflamed and produce extra mucus over time?','Chronic bronchitis',['Seasonal allergies','Acute sinus cold','Nosebleeds'],'B','Chronic bronchitis is a form of COPD often caused by smoking.',HART),
  q(BODY,'Which finding is a common sign of a stroke affecting the face?','Drooping on one side',['Even, symmetrical smile','Red, itchy cheeks','Puffy eyes in the morning'],'C','Use BE FAST to check balance, eyes, face, arms and speech, then call 911.',HART),
  q(BODY,'Which is the largest organ of the body?','The skin',['The liver','The brain','The lungs'],'D','The skin protects the body, controls temperature and senses touch.',HART),
  q(BODY,'Which sign should be reported for a client with kidney disease?','Swelling and less urine',['Clear urine and thirst','Good appetite and energy','Regular bowel habits'],'A','Less urine and swelling suggest fluid is building up in the body.',HART),
  q(SPEC,'A client who is deaf uses sign language. How should the aide help communication?','Use written notes or an interpreter',['Shout so the client can hear you','Speak only to the client’s family','Avoid talking to the client at all'],'B','Agencies can arrange interpreters, and writing notes helps between visits.',HART),
  q(SPEC,'Which change is common in clients with late-stage dementia?','Trouble swallowing',['Better memory skills','Faster walking pace','Learning new skills'],'C','Swallowing problems raise the risk of choking and aspiration pneumonia.',HART),
  q(SPEC,'What is sundowning in a client with dementia?','Increased confusion in the late day',['Sleeping well through the night','Better mood in the evening hours','Waking up early every morning'],'D','Keeping lights on and a calm routine in the evening can help.',HART),
  q(SPEC,'Which activity is appropriate for a client with dementia?','Folding towels',['Balancing a checkbook','Learning a new language','Driving to the store'],'A','Simple, familiar tasks give a sense of purpose without causing frustration.',HART),
  q(SPEC,'Which approach is best for a client with a developmental disability?','Treat the client with respect for their age',['Speak to the client like a small child','Do every task for the client','Keep the client away from others'],'B','Clients should be encouraged to be as independent as possible.',HART),
  q(SPEC,'Which is a goal of hospice care?','Comfort and quality of life',['Curing the client’s illness','Starting new chemotherapy','Adding surgeries to extend life'],'C','Hospice focuses on comfort, dignity and support for the family.',HART),
  q(SPEC,'Which breathing change is common in the last days of life?','Cheyne-Stokes breathing',['Steady, deep and even breaths','Normal, quiet breaths at rest','Fast breathing during exercise'],'D','Periods of deep breathing alternate with pauses as death nears.',HART),
  q(SPEC,'What should an aide do for a new mother who is breastfeeding?','Encourage fluids and rest',['Limit her fluid intake','Wake her every hour at night','Tell her to stop nursing'],'A','Nursing mothers need extra fluids and rest to make milk and recover.',HART),
  q(SPEC,'How should a newborn be bathed until the umbilical cord falls off?','Sponge bath only',['Tub bath daily','Shower with parent','Swim in the pool'],'B','The cord stump should stay dry until it falls off, usually in 1 to 2 weeks.',HART),
  q(SPEC,'Which sign of depression in an older adult should the aide report?','Loss of interest in activities',['Enjoying visits from family','Eating meals with others','Reading the newspaper daily'],'C','Depression is not a normal part of aging; it can be treated and should be reported.',HART),
  q(SPEC,'A client with a mental illness hears voices. What is the best response?','Stay calm and report it',['Argue that voices are fake','Laugh to ease the tension','Leave the client alone all day'],'D','Hallucinations feel real to the client, so the aide should not argue with them.',HART),
  q(SPEC,'Which practice helps a child with a chronic illness at home?','Keep routines as normal as possible',['Keep the child away from all friends','Stop all school activities forever','Avoid talking about the illness'],'A','Normal routines support the child’s development and sense of security.',HART),
  q(SKILL,'What is the normal range for an adult’s resting pulse?','60 to 100 beats per minute',['20 to 40 beats per minute','40 to 50 beats per minute','120 to 160 beats per minute'],'B','A resting adult pulse below 60 or above 100 should be reported to the nurse.',BAL),
  q(SKILL,'How should an aide help a client put on a shirt after a stroke affecting the right arm?','Dress the weak arm first',['Dress the strong arm first','Pull the shirt over quickly','Leave the weak arm out'],'C','Dress the weak side first and undress the strong side first so the weak arm moves less.',BAL),
  q(SKILL,'Which position is best for a client eating in bed?','Sitting upright',['Lying flat','Lying on the stomach','Head lower than feet'],'D','Sitting upright helps food go down the esophagus and prevents choking and aspiration.',BAL),
  q(SKILL,'How should an aide measure a client’s urine output?','Use a graduate and read at eye level',['Guess the amount by looking','Weigh the bedpan on a scale','Count the number of trips'],'A','Accurate measurement is important for clients on intake and output records.',BAL),
  q(SKILL,'When giving a back rub, which finding should the aide report?','Red areas that do not fade',['Warm skin from the lotion','Relaxed muscles after rub','Client falling asleep'],'B','Redness that does not fade after pressure is removed may be an early pressure injury.',BAL)
 ],7020)
};
